def time_until_both_trains_leave():
    train_a_interval = 16
    train_b_interval = 17

    # The time until both trains leave simultaneously is the least common multiple (LCM) of their intervals
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def lcm(x, y):
        return x * y // gcd(x, y)

    time_until_simultaneous_departure = lcm(train_a_interval, train_b_interval)
    return time_until_simultaneous_departure

